import{_ as e,o as a,c as i,a2 as r}from"./chunks/framework.Lq8Lraw_.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Git 精通之路","text":"从第一次提交，到企业级冲突治理","tagline":"不只教你敲命令，更教你判断「什么时候该用 merge、rebase 还是 cherry-pick」，以及用错之后如何全身而退。","image":{"src":"/logo.svg","alt":"Git 精通之路"},"actions":[{"theme":"brand","text":"从入门开始","link":"/guide/basics/01-version-control"},{"theme":"alt","text":"直达协作篇","link":"/guide/collaboration/01-remote-workflow"},{"theme":"alt","text":"命令速查","link":"/guide/appendix/01-cheatsheet"}]},"features":[{"title":"由浅入深，没有跳跃","details":"从版本控制的概念讲起，三区模型、分支引用、合并原理逐层拆解。每一章都能独立跑通，不假设你背过命令。"},{"title":"冲突讲透，而不是绕开","details":"用三方合并模型解释冲突从哪里来，再对照 merge、rebase、cherry-pick 的适用边界，给出可直接照做的决策表。"},{"title":"六个企业级实战场景","details":"同文件冲突、分支落后主干、误提交到错误分支、hotfix 回灌、历史整理后强推、线上错误提交回滚，全部按「错误示范 → 正确操作 → 命令注释 → 分支图」展开。"},{"title":"每一步都有退路","details":"reflog、revert、--force-with-lease、rerere 等安全网贯穿全书，先讲风险与适用边界，再讲具体用法。"},{"title":"分支模型选型","details":"Git Flow、GitHub Flow、Trunk-Based Development 三种主流模型对比，给出团队规模与发布节奏对应的选择建议。"},{"title":"可查询、可复制","details":"全站本地搜索，附命令速查表、报错 FAQ 和推荐 alias，排查问题时不用翻聊天记录。"},{"title":"底层原理，能解释行为","details":"对象模型、引用体系、索引三棵树，用可复现实验解释 reflog、rebase、冲突为什么会这样表现。"},{"title":"规模化与 CI","details":"浅克隆陷阱、worktree、sparse checkout、partial clone、LFS 与仓库维护，覆盖团队变大后暴露的问题。"},{"title":"治理与安全","details":"签名、服务端 hooks、分支保护与 CODEOWNERS，从个人精通走到能制定团队规范。"},{"title":"交互演练场","details":"浏览器里可视化三方合并与 revision 语法，改一改选择就能看到冲突标记和命中提交的变化。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793619381000}'),o={name:"index.md"};function l(d,t,s,n,c,g){return a(),i("div",null,[...t[0]||(t[0]=[r('<h2 id="这套教程怎么用" tabindex="-1">这套教程怎么用 <a class="header-anchor" href="#这套教程怎么用" aria-label="Permalink to &quot;这套教程怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>建议路线</th></tr></thead><tbody><tr><td>刚接触 Git，只会 <code>clone</code> 和 <code>pull</code></td><td>入门篇 → 进阶篇 → 协作篇第 11、12 章</td></tr><tr><td>日常开发够用，但一遇到冲突就慌</td><td>协作篇第 12～16 章，配合第 18 章实战</td></tr><tr><td>团队协作混乱，想定规范</td><td><a href="/git-tutorial-site/guide/collaboration/03-merge-vs-rebase">merge vs rebase</a> → <a href="/git-tutorial-site/guide/collaboration/09-branching-models">分支模型选型</a> → <a href="/git-tutorial-site/guide/mastery/04-hooks">hooks</a> → <a href="/git-tutorial-site/guide/governance/01-signing">签名</a> → <a href="/git-tutorial-site/guide/governance/02-server-hooks-policy">服务端 hooks 与分支治理</a></td></tr><tr><td>想理解 Git 为什么这样表现</td><td><a href="/git-tutorial-site/guide/internals/01-object-model">对象模型</a> → <a href="/git-tutorial-site/guide/internals/02-refs-and-revisions">引用体系</a> → <a href="/git-tutorial-site/guide/internals/03-index-and-three-trees">索引与三棵树</a></td></tr><tr><td>仓库太大、CI 很慢</td><td><a href="/git-tutorial-site/guide/scale/01-git-in-ci">CI 中的 Git</a> → <a href="/git-tutorial-site/guide/scale/02-worktree-sparse-partial">worktree / sparse / partial clone</a> → <a href="/git-tutorial-site/guide/scale/03-lfs">LFS</a> → <a href="/git-tutorial-site/guide/scale/04-maintenance">仓库维护</a></td></tr><tr><td>想整理历史、清理误提交的密钥</td><td><a href="/git-tutorial-site/guide/collaboration/10-rebase-deep-dive">rebase 深水区</a> → <a href="/git-tutorial-site/guide/collaboration/11-history-rewrite">历史重写与脱敏</a></td></tr><tr><td>想查某行代码的来历</td><td><a href="/git-tutorial-site/guide/mastery/06-archaeology">提交考古</a> → <a href="/git-tutorial-site/guide/mastery/07-tracing">Git 追踪调试</a></td></tr><tr><td>想动手试一遍</td><td><a href="/git-tutorial-site/playground/">交互演练场</a></td></tr><tr><td>误删分支 / 误 reset，急需救火</td><td><a href="/git-tutorial-site/guide/mastery/01-reflog">reflog：误操作的后悔药</a></td></tr><tr><td>只想查命令</td><td><a href="/git-tutorial-site/guide/appendix/01-cheatsheet">命令速查表</a></td></tr></tbody></table><h2 id="阅读约定" tabindex="-1">阅读约定 <a class="header-anchor" href="#阅读约定" aria-label="Permalink to &quot;阅读约定&quot;">​</a></h2><ul><li>示例基于 Git 2.40+ 的常见行为编写，可直接照抄；输出中的哈希与路径以实际仓库为准。</li><li>命令块以 <code>#</code> 开头的行是注释，不需要输入。</li><li>「分支图」统一用 ASCII 或 SVG 表示：<code>*</code> 是提交，<code>\\</code> 与 <code>/</code> 表示分叉与汇合，括号内是分支名。</li><li>新增章节的图解统一使用 SVG，颜色随明暗模式自动切换；图下会标注该图想说明的结论。</li><li>涉及改写历史的操作（rebase、cherry-pick、reset --hard）都会用提示块标注风险与适用边界。</li></ul><div class="warning custom-block"><p class="custom-block-title">关于改写历史</p><p>本教程反复强调一条底线：<strong>已经被他人拉取的公共分支，不要 rebase，也不要 reset 后强推</strong>。协作篇第 13 章会用分支图解释这条规则为什么不是教条，而是数学结果。</p></div>',5)])])}const f=e(o,[["render",l]]);export{u as __pageData,f as default};
